import 'dart:io';

import 'package:hyena_dart/src/analyzer/generated_file.dart';
import 'package:test/test.dart';

void main() {
  group('generated headers', () {
    for (final source in [
      '// GENERATED CODE - DO NOT MODIFY BY HAND\nclass C {}',
      '\uFEFF\n// license\n/* generated code - do not modify by hand */\n',
      '// Code generated by a tool. DO NOT EDIT.\n',
    ]) {
      test('recognizes $source', () {
        expect(GeneratedFiles.hasGeneratedHeader(source), isTrue);
      });
    }
    for (final source in [
      '',
      'class C {} // GENERATED CODE - DO NOT MODIFY BY HAND',
      'import "x.dart";\n// GENERATED CODE - DO NOT MODIFY BY HAND',
      'const s = "GENERATED CODE - DO NOT MODIFY BY HAND";',
      '// A discussion of GENERATED CODE - DO NOT MODIFY BY HAND\n',
      '/* GENERATED CODE - DO NOT MODIFY BY HAND',
    ]) {
      test('does not classify $source', () {
        expect(GeneratedFiles.hasGeneratedHeader(source), isFalse);
      });
    }
    test('preserves suffixes and handles unreadable paths', () {
      final files = GeneratedFiles();
      final directory = Directory.systemTemp.createTempSync('hyena_header_');
      addTearDown(() => directory.deleteSync(recursive: true));
      for (final suffix in ['.g.dart', '.freezed.dart', '.mocks.dart']) {
        expect(files.contains('${directory.path}/missing$suffix'), isTrue);
      }
      expect(files.contains('${directory.path}/missing.dart'), isFalse);
    });
  });
}
